```php
<?php

namespace App\Http\Controllers;

use App\Models\Task;
use App\Models\User;
use Illuminate\Http\Request;

class TaskController extends Controller
{
    /**
     * Get all tasks without filtering by the current user.
     *
     * @return \Illuminate\Http\JsonResponse
     */
    public function GeneralTask()
    {
        // Fetch all tasks. 
        // If you need to include related data (like the user who assigned it), 
        // you can use 'with' as shown below.
        $tasks = Task::with(['user', 'assignee'])->get();

        return response()->json([
            'success' => true,
            'data' => $tasks
        ]);
    }
}
```

